}

Method.Source:
/// <summary>
/// Setting the default value of METReceiptQuantity
/// </summary>
/// <param name = "_parmLine">Purch parmline buffer</param>
protected void insertParmLine(Common _parmLine)
{
    PurchParmLine parmLine = _parmLine as PurchParmLine;

    parmLine.METReceiptQuantity = parmLine.ReceiveNow;

    next insertParmLine(parmLine);
}
